<?php
require_once __DIR__ . '/_helpers.php';auth_require_login();if(!auth_can_view_module('medicos')&&!auth_can_view_module('horarios'))medicos_json(false,'Sin permiso.',[],403);
try{$sql="SELECT m.id,m.nombre,m.color,GROUP_CONCAT(CONCAT(e.id,'|',e.nombre,'|',me.principal) ORDER BY me.principal DESC,e.nombre SEPARATOR ';;') especialidades FROM medicos_iphci m JOIN medicos_especialidades me ON me.medico_id=m.id JOIN especialidades_medicas e ON e.id=me.especialidad_id AND e.activo=1 WHERE m.activo=1 GROUP BY m.id ORDER BY m.nombre";$rows=$pdo->query($sql)->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r){$r['id']=(int)$r['id'];$r['especialidades']=medicos_parse_specialties($r['especialidades']);}medicos_json(true,'',['records'=>$rows]);}catch(Throwable $e){medicos_json(false,'No se pudieron cargar los profesionales.',[],500);}
